private getOrCompileValidator(schema: Record<string, unknown>): ValidateFunction {
  const cached = this.validatorCache.get(schema);
  if (cached) {
    return cached;
  }

  const compiled = ajv.compile(schema);
  this.validatorCache.set(schema, compiled);
  return compiled;
}

