        return `${path} ${e.message ?? 'invalid'} (expected ${expected ?? e.keyword})`;
      })
      .join('; ');

    log.warn('tool', 'validation failed', {name, errorDetail});
    return {result: `Validation failed: ${errorDetail}`};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);

