import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import Ajv from 'ajv';

describe('ToolRegistry', () => {
  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();
    const invalidSchema: ToolDefinition = {
      name: 'broken-tool',
      description: 'A tool with a broken schema',
      inputSchema: {
        type: 'object',
        properties: {
          age: {type: 'number', minimum: 'not-a-number' as any}, // Invalid JSON Schema
        },
      },
    };

    expect(() => registry.register(invalidSchema, async () => 'ok')).toThrow(/broken-tool/);
  });

  it('validates against the schema current at that call for a function-valued tool definition', async () => {
    const registry = new ToolRegistry();
    let schemaType = 'string';
    const definitionSource = () => ({
      name: 'dynamic-tool',
      description: 'A tool with a dynamic schema',
      inputSchema: {
        type: 'object',
        properties: {
          val: {type: schemaType},
        },
        required: ['val'],
      },
    });

    const executor = jest.fn<any>().mockResolvedValue('ok');
    registry.register(definitionSource, executor as any);

    // First call: schema requires string
    await registry.execute('dynamic-tool', {val: 'hello'});
    expect(executor).toHaveBeenCalledWith({val: 'hello'}, undefined);

    // Second call: schema requires string, but we pass number
    const response = await registry.execute('dynamic-tool', {val: 123});
    expect(response.result).toMatch(/val/);
    expect(response.result).toMatch(/string/);
    expect(executor).toHaveBeenCalledTimes(1);

    // Change schema to require number
    schemaType = 'number';
    await registry.execute('dynamic-tool', {val: 123});
    expect(executor).toHaveBeenCalledTimes(2);
    expect(executor).toHaveBeenLastCalledWith({val: 123}, undefined);
  });

  it('compiles a static tool schema once and reuses it', async () => {
    const registry = new ToolRegistry();
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');

    registry.register(
      {
        name: 'static-tool',
        description: 'desc',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async () => 'ok'
    );

    expect(compileSpy).toHaveBeenCalledTimes(1);

    for (let i = 0; i < 10; i++) {
      await registry.execute('static-tool', {a: 'val'});
    }

    expect(compileSpy).toHaveBeenCalledTimes(1);
    compileSpy.mockRestore();
  });
});

